#include <iostream>
#include <memory>
#include <vector>
#include <utility>
#include <string>

struct CountingDelete { int* count; void operator()(int* p) const noexcept { ++*count; delete p; } };
int solve(int a, int b) { int count = 0; std::unique_ptr<int, CountingDelete> p(new int(a), CountingDelete{&count}); auto q = std::move(p); int saved = *q + b; q.reset(); q.reset(); return count == 1 ? saved : -9999; }
